INSERT INTO tracks VALUES
('BATTER_S1_007_termseq_teps', 'GCF_000739105.1', 'BATTER_S1_007', 2019, '31555254', 'records/BATTER_S1_007.html', 'The Transcription Unit Architecture of Streptomyces lividans TK24', 'https://pubmed.ncbi.nlm.nih.gov/31555254/', 'PRJEB31507', 'https://www.ebi.ac.uk/ena/browser/view/PRJEB31507', 'Author-reported transcript 3′-end positions (TEPs); this experiment does not distinguish transcription termination from RNA processing.', '作者报告的转录本 3′ 端位置（TEP）；该实验不能区分转录终止与 RNA 加工。', '{"source_role":"Original organism-specific study","source_role_zh":"原始物种研究","lead_institution":"Korea Advanced Institute of Science and Technology (KAIST)","lead_laboratory":"Systems and Synthetic Biology Laboratory, Department of Biological Sciences and KI for the BioCentury","country":"South Korea","country_zh":"韩国","corresponding_author":"Byung-Kwan Cho","ena_submitting_center":"KAIST","sequencing_facility":"Not separately reported","sequencing_facility_zh":"论文和 ENA 未单独说明测序机构","culture_condition":"R5− medium at 30 °C","culture_condition_zh":"R5− 培养基，30 °C","sampling_scheme":"9.5, 14, 16 and 20 h after inoculation; four growth phases","sampling_scheme_zh":"接种后 9.5、14、16 和 20 小时；覆盖四个生长阶段","biological_replicates":2,"sequencing_platform":"Illumina HiSeq 2500","read_layout":"Term-seq: single-end 50 bp","read_layout_zh":"Term-seq：单端 50 bp","data_relationship":"Primary S. lividans publication associated with PRJEB31507.","data_relationship_zh":"PRJEB31507 对应的 S. lividans 原始研究论文。"}', 'Author-called Term-seq TEPs (Lee 2019)', 'Term-seq / dRNA-seq', 'author_called_endpoint', 1640, 'GCF_000739105.1/tracks/BATTER_S1_007.endpoints.bed', 1),
('BATTER_S1_013_termseq_tts', 'GCF_000739105.1', 'BATTER_S1_013', 2020, '33319794', 'records/BATTER_S1_013.html', 'Genome-scale determination of 5′ and 3′ boundaries in Streptomyces genomes', 'https://pubmed.ncbi.nlm.nih.gov/33319794/', 'PRJEB31507', 'https://www.ebi.ac.uk/ena/browser/view/PRJEB31507', 'Author-reported Term-seq transcription termination sites (TTS); these coordinates are not automatically functional validation of each terminator.', '作者报告的 Term-seq 转录终止位点（TTS）；这些坐标不自动等同于每个终止子的功能验证。', '{"source_role":"Cross-species Scientific Data descriptor","source_role_zh":"跨物种 Scientific Data 数据论文","lead_institution":"Korea Advanced Institute of Science and Technology (KAIST)","lead_laboratory":"Department of Biological Sciences and KI for the BioCentury","country":"South Korea","country_zh":"韩国","corresponding_author":"Byung-Kwan Cho","ena_submitting_center":"KAIST","sequencing_facility":"Not separately reported","sequencing_facility_zh":"论文和 ENA 未单独说明测序机构","culture_condition":"R5− medium at 30 °C","culture_condition_zh":"R5− 培养基，30 °C","sampling_scheme":"9.5, 14, 16 and 20 h after inoculation; four growth phases","sampling_scheme_zh":"接种后 9.5、14、16 和 20 小时；覆盖四个生长阶段","biological_replicates":2,"sequencing_platform":"Illumina HiSeq 2500","read_layout":"Term-seq: single-end 50 bp","read_layout_zh":"Term-seq：单端 50 bp","data_relationship":"Uses the same S. lividans raw project PRJEB31507 and publishes a 1,208-site table in a seven-species comparison.","data_relationship_zh":"使用同一个 S. lividans 原始项目 PRJEB31507，并在七个物种的比较中发表 1,208 个端点。"}', 'Author-called Term-seq TTS (Lee 2020)', 'Term-seq / dRNA-seq', 'author_called_endpoint', 1208, 'GCF_000739105.1/tracks/BATTER_S1_013.endpoints.bed', 2);
